values ($lx$i-hui-chiang-md-phoenix$lx$, (select id from public.business_categories where slug = $lx$medical$lx$), $lx$I-Hui Chiang, MD (Banner Health)$lx$, null, $lx$Mandarin-speaking interventional cardiologist at the Banner - University Medicine Heart Institute in Phoenix, accepting new patients.$lx$, $lx$鳳凰城 Banner - University Medicine 心臟中心會說國語的介入性心臟科醫師，目前接受新病患。$lx$, $lx$Dr. I-Hui Chiang is a cardiologist and interventional cardiologist at the Banner - University Medicine Heart Institute, 755 E McDowell Rd, Floor 4, in Phoenix, and also sees patients at Banner Health Center plus at Arcadia on E Camelback Rd. Dr. Chiang treats adults and seniors and is accepting new patients. Dr. Chiang earned a medical degree at the University of Texas Southwestern Medical School, completed an internship and residency at UT Southwestern Medical Center and a fellowship at Baylor College of Medicine, and is board certified in cardiovascular disease. Banner lists English, Mandarin, Hokkien and French. Languages as listed in Banner Health's Find a Doctor directory, checked November 2026.$lx$, $lx$I-Hui Chiang 醫師是心臟內科及介入性心臟科醫師，在鳳凰城 755 E McDowell Rd 四樓的 Banner - University Medicine Heart Institute 看診，也在 E Camelback Rd 的 Banner Health Center plus at Arcadia 看診。看診對象為成人及長者，目前接受新病患。Chiang 醫師畢業於德州大學西南醫學院，在 UT Southwestern Medical Center 完成實習及住院醫師訓練，並在貝勒醫學院完成專科研修，持有心血管疾病專科認證。Banner 列出的語言為英語、國語、閩南語及法語。語言資訊依據 Banner Health「Find a Doctor」醫師名錄，2026 年 11 月查核。$lx$, $lx$Phoenix$lx$, $lx$Greater Phoenix$lx$, $lx$755 E McDowell Rd, Floor 4, Phoenix, AZ 85006$lx$, null, $lx$(602) 521-3090$lx$, null, $lx$https://doctors.bannerhealth.com/provider/i-hui-chiang/1458854$lx$, array[$lx$English$lx$, $lx$Mandarin$lx$]::text[], array[$lx$I-Hui Chiang, MD (Banner Health)$lx$, $lx$Phoenix$lx$, $lx$medical$lx$, $lx$doctors.bannerhealth.com$lx$, $lx$English$lx$, $lx$Mandarin$lx$, $lx$doctor physician$lx$, $lx$醫師 看診$lx$, $lx$Chinese-speaking$lx$, $lx$中文服務$lx$]::text[], true, true, false, false, false, $lx$live$lx$, $lx$editor_verified$lx$, now())
