values ($lx$rong-guo-md-glendale$lx$, (select id from public.business_categories where slug = $lx$medical$lx$), $lx$Rong Guo, MD (Banner Health)$lx$, null, $lx$Mandarin-speaking endocrinologist (diabetes, thyroid, metabolism) at Banner Health Center plus in Glendale, accepting new patients.$lx$, $lx$格倫代爾 Banner Health Center plus 會說國語的內分泌科醫師（糖尿病、甲狀腺、代謝），目前接受新病患。$lx$, $lx$Dr. Rong Guo is an endocrinologist at Banner Health Center plus, 7701 W Aspera Blvd, Suite 201, in Glendale, and treats adults. Dr. Guo is accepting new patients and is board certified in endocrinology, diabetes and metabolism by the American Board of Internal Medicine. Dr. Guo earned a medical degree at Shenyang Medical College, completed a residency at St. John's Episcopal Hospital South Shore and a fellowship at Northwestern University Feinberg School of Medicine. Dr. Guo speaks Mandarin and English. Languages as listed in Banner Health's Find a Doctor directory, checked November 2026.$lx$, $lx$Rong Guo 醫師是內分泌科醫師，在格倫代爾（Glendale）7701 W Aspera Blvd, Suite 201 的 Banner Health Center plus 看診，看診對象為成人。目前接受新病患，持有美國內科醫學委員會（ABIM）內分泌、糖尿病與代謝專科認證。Guo 醫師畢業於瀋陽醫學院，在 St. John's Episcopal Hospital South Shore 完成住院醫師訓練，並在西北大學 Feinberg 醫學院完成專科研修。能說國語及英語。語言資訊依據 Banner Health「Find a Doctor」醫師名錄，2026 年 11 月查核。$lx$, $lx$Glendale$lx$, $lx$Greater Phoenix$lx$, $lx$7701 W Aspera Blvd, Suite 201, Glendale, AZ 85308$lx$, null, $lx$(623) 248-2108$lx$, null, $lx$https://doctors.bannerhealth.com/provider/rong-guo/867400$lx$, array[$lx$English$lx$, $lx$Mandarin$lx$]::text[], array[$lx$Rong Guo, MD (Banner Health)$lx$, $lx$Glendale$lx$, $lx$medical$lx$, $lx$doctors.bannerhealth.com$lx$, $lx$English$lx$, $lx$Mandarin$lx$, $lx$doctor physician$lx$, $lx$醫師 看診$lx$, $lx$Chinese-speaking$lx$, $lx$中文服務$lx$]::text[], true, true, false, false, false, $lx$live$lx$, $lx$editor_verified$lx$, now())
