values ($lx$rosanne-kho-md-phoenix$lx$, (select id from public.business_categories where slug = $lx$medical$lx$), $lx$Rosanne Marie Kho, MD (Banner Health)$lx$, null, $lx$Mandarin-speaking gynecologic surgeon (minimally invasive surgery) at the Banner - University Medicine Women's Institute in Phoenix.$lx$, $lx$鳳凰城 Banner - University Medicine 婦女健康中心會說國語的微創婦科手術醫師。$lx$, $lx$Dr. Rosanne Marie Kho is a gynecologic surgeon specializing in minimally invasive gynecologic surgery at the Banner - University Medicine Women's Institute, 1441 N 12th St, Floor 3, in Phoenix. Dr. Kho treats adults and is accepting new patients. Dr. Kho earned a medical degree at Tulane University, trained at the Mayo Clinic College of Medicine and Science with a fellowship at Mayo Clinic in Scottsdale, and is board certified by the American Board of Obstetrics and Gynecology. Banner lists English, Mandarin, Min Nan Chinese and Tagalog. Languages as listed in Banner Health's Find a Doctor directory, checked November 2026.$lx$, $lx$Rosanne Marie Kho 醫師是婦科外科醫師，專長微創婦科手術，在鳳凰城 1441 N 12th St 三樓的 Banner - University Medicine Women's Institute 看診。看診對象為成人，目前接受新病患。Kho 醫師畢業於杜蘭大學醫學院，在梅奧醫學院（Mayo Clinic College of Medicine and Science）接受訓練，並在斯科茨代爾梅奧診所完成專科研修，持有美國婦產科醫學委員會專科認證。Banner 列出的語言為英語、國語、閩南語及他加祿語。語言資訊依據 Banner Health「Find a Doctor」醫師名錄，2026 年 11 月查核。$lx$, $lx$Phoenix$lx$, $lx$Greater Phoenix$lx$, $lx$1441 N 12th St, Floor 3, Phoenix, AZ 85006$lx$, null, $lx$(602) 521-5700$lx$, null, $lx$https://doctors.bannerhealth.com/provider/rosanne-marie-kho/2443333$lx$, array[$lx$English$lx$, $lx$Mandarin$lx$]::text[], array[$lx$Rosanne Marie Kho, MD (Banner Health)$lx$, $lx$Phoenix$lx$, $lx$medical$lx$, $lx$doctors.bannerhealth.com$lx$, $lx$English$lx$, $lx$Mandarin$lx$, $lx$doctor physician$lx$, $lx$醫師 看診$lx$, $lx$Chinese-speaking$lx$, $lx$中文服務$lx$]::text[], true, true, false, false, false, $lx$live$lx$, $lx$editor_verified$lx$, now())
