values ($lx$ying-li-md-phoenix$lx$, (select id from public.business_categories where slug = $lx$medical$lx$), $lx$Ying Li, MD, PhD (Banner MD Anderson)$lx$, null, $lx$Mandarin-speaking radiation oncologist with Banner MD Anderson Cancer Center in Phoenix, accepting new patients.$lx$, $lx$Banner MD Anderson 癌症中心會說國語的放射腫瘤科醫師，目前接受新病患。$lx$, $lx$Dr. Ying Li (MD, PhD) is a radiation oncologist with Banner MD Anderson Cancer Center at Banner University Medical Center - Phoenix, 925 E McDowell Rd, and is also listed at other Banner MD Anderson sites, including Banner Thunderbird Medical Center in Glendale. Dr. Li treats adults and is accepting new patients. Dr. Li completed an internal medicine internship and a residency at the State University of New York at Buffalo and is board certified by the American Board of Radiology. Dr. Li speaks Mandarin and English. The phone number is the Banner MD Anderson scheduling line shown on the Banner profile. Languages as listed in Banner Health's Find a Doctor directory, checked November 2026.$lx$, $lx$Ying Li 醫師（醫學博士兼哲學博士）是放射腫瘤科醫師，在 Banner University Medical Center - Phoenix（925 E McDowell Rd）的 Banner MD Anderson 癌症中心看診，也列於其他 Banner MD Anderson 據點，包括格倫代爾的 Banner Thunderbird Medical Center。看診對象為成人，目前接受新病患。Li 醫師在紐約州立大學水牛城分校完成內科實習及住院醫師訓練，持有美國放射醫學委員會專科認證。能說國語及英語。電話為 Banner 醫師頁面所列的 Banner MD Anderson 預約專線。語言資訊依據 Banner Health「Find a Doctor」醫師名錄，2026 年 11 月查核。$lx$, $lx$Phoenix$lx$, $lx$Greater Phoenix$lx$, $lx$925 E McDowell Rd, Phoenix, AZ 85006$lx$, null, $lx$(480) 256-6444$lx$, null, $lx$https://doctors.bannerhealth.com/provider/ying-li/885083$lx$, array[$lx$English$lx$, $lx$Mandarin$lx$]::text[], array[$lx$Ying Li, MD, PhD (Banner MD Anderson)$lx$, $lx$Phoenix$lx$, $lx$medical$lx$, $lx$doctors.bannerhealth.com$lx$, $lx$English$lx$, $lx$Mandarin$lx$, $lx$doctor physician$lx$, $lx$醫師 看診$lx$, $lx$Chinese-speaking$lx$, $lx$中文服務$lx$]::text[], true, true, false, false, false, $lx$live$lx$, $lx$editor_verified$lx$, now())
