values ($lx$angela-feng-do-mesa$lx$, (select id from public.business_categories where slug = $lx$medical$lx$), $lx$Angela Feng, DO (Banner Health)$lx$, null, $lx$Cantonese-speaking family medicine doctor at Banner Health Clinic in Mesa, accepting new patients.$lx$, $lx$梅薩 Banner Health Clinic 會說粵語的家庭醫學科醫師，目前接受新病患。$lx$, $lx$Dr. Angela Feng is a family medicine physician (DO) at Banner Health Clinic, 1300 S Country Club Dr, Suite 3, in Mesa, and cares for teenagers, adults and seniors. Dr. Feng is accepting new patients and is board certified by the American Board of Family Medicine. Dr. Feng earned a medical degree at Michigan State University College of Osteopathic Medicine and completed a residency at St. Mary Mercy Livonia. Dr. Feng speaks Cantonese and English. Languages as listed in Banner Health's Find a Doctor directory, checked November 2026.$lx$, $lx$Angela Feng 醫師是家庭醫學科醫師（DO），在梅薩（Mesa）1300 S Country Club Dr, Suite 3 的 Banner Health Clinic 看診，看診對象為青少年、成人及長者。目前接受新病患，持有美國家庭醫學委員會專科認證。Feng 醫師畢業於密西根州立大學骨科醫學院，並在 St. Mary Mercy Livonia 完成住院醫師訓練。能說粵語及英語。語言資訊依據 Banner Health「Find a Doctor」醫師名錄，2026 年 11 月查核。$lx$, $lx$Mesa$lx$, $lx$Greater Phoenix$lx$, $lx$1300 S Country Club Dr, Suite 3, Mesa, AZ 85210$lx$, null, $lx$(480) 827-5500$lx$, null, $lx$https://doctors.bannerhealth.com/provider/angela-feng/1080541$lx$, array[$lx$English$lx$, $lx$Cantonese$lx$]::text[], array[$lx$Angela Feng, DO (Banner Health)$lx$, $lx$Mesa$lx$, $lx$medical$lx$, $lx$doctors.bannerhealth.com$lx$, $lx$English$lx$, $lx$Cantonese$lx$, $lx$doctor physician$lx$, $lx$醫師 看診$lx$, $lx$Chinese-speaking$lx$, $lx$中文服務$lx$]::text[], true, true, false, false, false, $lx$live$lx$, $lx$editor_verified$lx$, now())
